#!/usr/bin/env python3
"""M1 decision summary: ngram self-speculation on real traffic.

Usage:
    python3 bench/spec_summarize.py [OUTDIR]

OUTDIR defaults to the newest bench/results/<date>/m1-ngram directory that
contains a replay/ sub-directory. Reads:

    OUTDIR/replay/<config>-<sampling>/requests.jsonl
    OUTDIR/replay/<config>-<sampling>/notes.txt
    OUTDIR/replay/<config>-<sampling>/vram.txt
    OUTDIR/replay/<config>-<sampling>/server_<phase>.log
    bench/.replay/outputs/<config>-<sampling>.jsonl   (gitignored, host only;
                                                        full message text)

Writes OUTDIR/summary.md and OUTDIR/summary.json. When no arm qualifies for
deployment, also writes OUTDIR/deploy.json =
    {"deployed": false, "why": ["<rule N>: <value> ..."]}.
If an arm qualifies, summary.md/summary.json mark it deploy-warranted and
leave deploy.json for the infra request (the returned JSON replaces it).

Metrics use foreground (fg) rows only.
  token-weighted decode tok/s = sum(predicted_n) / sum(predicted_ms) * 1000
  acceptance = sum(draft_n_accepted) / sum(draft_n)
  null/0 draft fields mean 0 drafted (llama.cpp returns draft_n /
  draft_n_accepted only when > 0; server-common.cpp:82-85).

Deployment rules (all must hold for the best spec arm, prod sampling unless
noted):
  1. the arm ran with the pinned --mmproj line (live entry) in every phase,
     and no -nommproj fallback was needed
  2. best spec arm prod dual-agent fg tok/s >= 1.10 x off
  3. spec arm prod dual-mem, single-agent and single-mem fg tok/s
     >= 0.97 x off
  4. spec arm VRAM (after first fg request, every phase) <= off + 64 MiB
  5. spec arm tool_call_json_valid rate >= off rate (greedy and prod,
     per phase)
  6. greedy identical-output rate (same phase + id vs off) is not below the
     off dual-vs-single control rate (batching baseline) by more than 10
     percentage points
"""
import json
import os
import re
import statistics
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT_ROOT = os.path.join(ROOT, "bench", "results")
FULL_OUT_ROOT = os.path.join(ROOT, "bench", ".replay", "outputs")
PHASES = ["single-agent", "single-mem", "dual-agent", "dual-mem"]
SAMPLINGS = ["greedy", "prod"]
CONFIGS = ["off", "A", "B"]


def abspath_outdir():
    outdir = sys.argv[1] if len(sys.argv) > 1 else None
    if outdir:
        return os.path.abspath(outdir)
    cands = []
    for d in os.listdir(OUT_ROOT):
        if os.path.isdir(os.path.join(OUT_ROOT, d, "m1-ngram", "replay")):
            cands.append(os.path.join(OUT_ROOT, d, "m1-ngram"))
    if not cands:
        sys.exit("error: no bench/results/<date>/m1-ngram/replay; pass OUTDIR")
    return max(cands)


def rows_for(outdir, arm):
    p = os.path.join(outdir, "replay", arm, "requests.jsonl")
    if not os.path.exists(p):
        return None
    rows = []
    with open(p) as f:
        for ln in f:
            if ln.strip():
                rows.append(json.loads(ln))
    return rows if rows else None


def discover_arms(outdir):
    rp = os.path.join(outdir, "replay")
    arms = []
    for name in sorted(os.listdir(rp)):
        if name.endswith("-nommproj"):
            continue
        d = os.path.join(rp, name)
        if os.path.isdir(d) and os.path.exists(os.path.join(d, "requests.jsonl")):
            arms.append(name)
    return arms


def arm_config(arm):
    return arm.rsplit("-", 1)[0]


def arm_sampling(arm):
    return arm.rsplit("-", 1)[1]


def fg_rows(rows, phase):
    return [r for r in rows if r.get("fg_bg") == "fg" and r.get("phase") == phase]


def rate(rs):
    ms = sum((r.get("predicted_ms") or 0) for r in rs)
    if not ms:
        return None
    return 1000.0 * sum((r.get("predicted_n") or 0) for r in rs) / ms


def median_toks(rs):
    vals = [(r["predicted_n"] / r["predicted_ms"]) * 1000.0
            for r in rs if (r.get("predicted_ms") or 0) > 0 and r.get("predicted_n", 0)]
    return statistics.median(vals) if vals else None


def acceptance(rs):
    dn = sum((r.get("draft_n") or 0) for r in rs)
    if not dn:
        return None
    da = sum((r.get("draft_n_accepted") or 0) for r in rs)
    return da / dn


def draft_per_gen(rs):
    pn = sum((r.get("predicted_n") or 0) for r in rs)
    if not pn:
        return None
    return sum((r.get("draft_n") or 0) for r in rs) / pn


def valid_rate(rs):
    if not rs:
        return None
    return sum(1 for r in rs if r.get("tool_call_json_valid")) / len(rs)


def vram_mib(outdir, arm, phase):
    p = os.path.join(outdir, "replay", arm, "vram.txt")
    used = {}
    try:
        cur = None
        with open(p) as f:
            for ln in f:
                m = re.match(r"^\s*==\s*(\S+?)\s*\(", ln)
                if m:
                    cur = m.group(1)
                    continue
                mv = re.search(r"([\d.]+)\s*MiB", ln)
                if cur and mv:
                    used[cur] = float(mv.group(1))
    except OSError:
        pass
    return used.get(phase)


def cmd_of(outdir, arm):
    p = os.path.join(outdir, "replay", arm, "notes.txt")
    try:
        with open(p) as f:
            for ln in f:
                if ln.startswith("cmd: "):
                    return ln[len("cmd: "):].strip()
    except OSError:
        pass
    return None


def warning_of(outdir, arm):
    """ngram quality warning from notes.txt, if present (e.g. 'too small')."""
    p = os.path.join(outdir, "replay", arm, "notes.txt")
    try:
        with open(p) as f:
            for ln in f:
                m = re.search(r"ngram_mod n_match=\d+ is too small", ln)
                if m:
                    return ln.strip()
    except OSError:
        pass
    return None


def load_full_outputs(label, sampling):
    p = os.path.join(FULL_OUT_ROOT, f"{label}-{sampling}.jsonl")
    if not os.path.exists(p):
        return None
    d = {}
    with open(p) as f:
        for ln in f:
            if not ln.strip():
                continue
            r = json.loads(ln)
            if r.get("fg_bg") == "fg":
                d[(r.get("phase"), r.get("id"))] = r
    return d


def blob_of(m):
    """Exactly the blob spec_replay.py hashed (same order, same json.dumps)."""
    tcs = m.get("tool_calls") or []
    return ((m.get("reasoning_content") or "")
            + (m.get("content") or "")
            + json.dumps(tcs, sort_keys=True))


def first_diff(a, b):
    for i, (ca, cb) in enumerate(zip(a, b)):
        if ca != cb:
            return i
    if len(a) != len(b):
        return min(len(a), len(b))
    return -1


def compare_rows(off_rows, off_full, spec_rows, spec_full, phase):
    """Compare spec fg rows against off fg rows (same phase/id). Returns dict."""
    out = {"n": len(spec_rows), "same": 0, "mismatches": [], "missing": []}
    for r in spec_rows:
        o = next((x for x in off_rows if x.get("phase") == phase
                  and x.get("id") == r.get("id")), None)
        if o is None:
            out["missing"].append(r["id"])
            continue
        if o.get("out_sha256") == r.get("out_sha256"):
            out["same"] += 1
            continue
        idx = None
        note = "sha differs"
        if off_full is not None and spec_full is not None:
            om = off_full.get((phase, r["id"]))
            sm = spec_full.get((phase, r["id"]))
            if om and sm:
                a = blob_of(om.get("message", {}))
                b = blob_of(sm.get("message", {}))
                if a == b:
                    idx = -1
                    note = "blobs equal (sha mismatch?)"
                else:
                    idx = first_diff(a, b)
                    note = "first divergence at char %d" % idx
        out["mismatches"].append({
            "id": r["id"], "idx": idx, "note": note})
    return out


def main():
    outdir = abspath_outdir()
    replay = os.path.join(outdir, "replay")
    arms = discover_arms(outdir)
    missing_arms = [a for a in ("off-greedy", "off-prod", "A-greedy", "A-prod",
                                 "B-greedy") if a not in arms]
    data = {a: rows_for(outdir, a) for a in arms}

    # ---- metrics per (config, sampling, phase) using fg rows only ----
    metric_rows = []
    rates = {}  # (config, sampling, phase) -> rate
    for arm in arms:
        rows = data[arm]
        for phase in PHASES:
            rs = fg_rows(rows, phase)
            role = rs[0]["role"] if rs else "n/a"
            r = rate(rs)
            rates[(arm_config(arm), arm_sampling(arm), phase)] = r
            metric_rows.append({
                "config": arm_config(arm), "sampling": arm_sampling(arm),
                "phase": phase, "role": role, "n": len(rs),
                "tok_s": r,
                "median_toks_s": median_toks(rs),
                "acceptance": acceptance(rs),
                "draft_tokens_per_generated_token": draft_per_gen(rs),
                "tool_call_json_valid": valid_rate(rs),
                "vram_mib": vram_mib(outdir, arm, phase),
            })
    for mr in metric_rows:
        c, s = mr["config"], mr["sampling"]
        off_r = rates.get(("off", s, mr["phase"]))
        mr["speedup_vs_off"] = (mr["tok_s"] / off_r if off_r else None)
        off_v = vram_mib(outdir, f"off-{s}", mr["phase"])
        v = mr["vram_mib"]
        mr["vram_delta_mib"] = (v - off_v) if v is not None and off_v is not None else None

    # ---- identity table (greedy only) ----
    greedy_arms = [a for a in arms if arm_sampling(a) == "greedy"]
    off_full = {}
    spec_full = {}
    for a in greedy_arms:
        off_full[arm_config(a)] = load_full_outputs("off", "greedy")
        spec_full[arm_config(a)] = load_full_outputs(arm_config(a), "greedy")
    off_g = rows_for(outdir, "off-greedy") if "off-greedy" in data else None
    identity = []
    control = {}
    for phase in PHASES:
        dual = phase if phase.startswith("dual-") else phase.replace("dual-", "single-")
        single = phase.replace("dual-", "single-") if phase.startswith("dual-") else phase.replace("single-", "dual-")
        # control: off dual fg vs off single fg, same id
        cd = fg_rows(off_g, dual) if off_g else []
        cs = fg_rows(off_g, single) if off_g else []
        ctl = compare_rows(None if off_g else off_g, off_g, None, None, "")  # placeholder
        ctl = {"n": len(cd), "same": 0, "mismatches": [], "missing": []}
        csha = {}
        if off_g:
            for r in fg_rows(off_g, single):
                csha[(r.get("phase"), r.get("id"))] = r.get("out_sha256")
        for r in cd:
            o = csha.get((single, r.get("id")))
            if o == r.get("out_sha256"):
                ctl["same"] += 1
                continue
            idx = None
            note = "sha differs"
            if off_full.get("off") is not None:
                dm = off_full["off"].get((dual, r.get("id")))
                sm = off_full["off"].get((single, r.get("id")))
                if dm and sm:
                    a = blob_of(dm.get("message", {}))
                    b = blob_of(sm.get("message", {}))
                    if a == b:
                        idx = -1
                        note = "blobs equal (sha mismatch?)"
                    else:
                        idx = first_diff(a, b)
                        note = "first divergence at char %d" % idx
            ctl["mismatches"].append({"id": r["id"], "idx": idx, "note": note})
        control[phase] = ctl

    identity = []
    for cfg in ["A", "B"]:
        for phase in PHASES:
            arm = f"{cfg}-greedy"
            if arm in data:
                o_full = spec_full.get("off")
                s_full = spec_full.get(cfg)
                off_p = fg_rows(off_g, phase) if off_g else []
                ctl = control.get(phase, {})
                cmp_ = compare_rows(off_p, None,
                                     fg_rows(data[arm], phase) if data.get(arm) else [],
                                     s_full, phase)
                cmp_["config"] = cfg
                cmp_["control_rate"] = (ctl["same"] / len(cd)) if (cd and ctl["n"]) else None
                cmp_["control_same"] = ctl["same"]
                cmp_["control_n"] = ctl["n"]
                cmp_["control_mismatches"] = ctl["mismatches"]
                cmp_["ident_rate"] = (cmp_["same"] / len(cmp_["mismatches"] + cmp_["same"])) \
                    if (cmp_["same"] + len(cmp_["mismatches"])) else None
                identity.append(cmp_)

    def pct(x):
        return "n/a" if x is None else f"{x * 100:.1f}%"

    def fnum(x, nd):
        return "n/a" if x is None else f"{x:.{nd}f}"

    def div_col(mismatches, limit=6):
        if not mismatches:
            return ""
        shown = []
        for m in mismatches[:limit]:
            idx = "n/a" if m["idx"] is None else str(m["idx"])
            shown.append("%s@%s" % (m["id"].rsplit("/", 1)[-1], idx))
        tail = ""
        if len(mismatches) > limit:
            idxs = [m["idx"] for m in mismatches if m["idx"] is not None]
            tail = ("; " + str(len(mismatches)) + " total, idx min/median/max "
                    + ("%d/%.0f/%d" % (min(idxs), statistics.median(idxs), max(idxs)) if idxs else "n/a"))
        return ", ".join(shown) + tail

    # ---- commands and warnings per arm ----
    cmds = {arm_config(a): cmd_of(outdir, a) for a in arms if cmd_of(outdir, a) is not None}
    warnings = {arm_config(a): warning_of(outdir, a) for a in arms
                if warning_of(outdir, a) is not None}

    # ---- decision rules on the best spec arm ----
    def off_rate(s, phase):
        return rates.get(("off", s, phase))

    spec_arms = [a for a in arms if arm_config(a) in ("A", "B")]
    def spec_rate(cfg, s, phase):
        return rates.get((cfg, s, phase))

    best_cfg = None
    best_val = -1
    for a in spec_arms:
        cfg = arm_config(a)
        v = spec_rate(cfg, "prod", "dual-agent")
        if v is not None and v > best_val:
            best_val = v
            best_cfg = cfg

    rule_details = []

    def rule(n, statement, ok, value):
        rule_details.append({"n": n, "rule": statement, "status": bool(ok),
                             "value": value})

    if best_cfg is None:
        rule_details.append({"n": 0, "rule": "no spec arm measurable", "status": False,
                             "value": "arms missing: %s" % missing_arms})
    else:
        # rule 1: mmproj pinned in every phase, no nommproj fallback
        r1 = []
        for phase in PHASES:
            c = cmds.get(best_cfg)
            if not c or not re.search(r"--mmproj\s+\S+", c):
                r1.append("%s: cmd lacks --mmproj" % phase)
        for a in spec_arms:
            if arm_config(a) == best_cfg and a.endswith("-nommproj"):
            r1.append("fallback -nommproj")
        rule(1, "spec arm ran with pinned --mmproj line (live entry) in every phase",
             not r1, "ok: all phases, cmd pinned" if not r1
             else "; ".join(r1))

        # rule 2: dual-agent prod >= 1.10x off
        v = best_val
        o = off_rate("prod", "dual-agent")
        ratio = v / o if o else None
        rule(2, "prod dual-agent fg tok/s >= 1.10x off",
             ratio is not None and ratio >= 1.10,
             f"{best_cfg}: {fnum(v, 1)} vs off {fnum(o, 1)} tok/s "
             f"= {ratio:.2f}x" if ratio is not None else "n/a")

        # rule 3: dual-mem, single-agent, single-mem >= 0.97x off (prod)
        r3_fail = []
        for phase in ["dual-mem", "single-agent", "single-mem"]:
            v = spec_rate(best_cfg, "prod", phase)
            o = off_rate("prod", phase)
            ratio = v / o if (v and o) else None
            if ratio is None or ratio < 0.97:
                r3_fail.append(f"{phase}: {fnum(v, 1)} vs off {fnum(o, 1)} "
                                f"= {ratio:.2f}x" if ratio is not None else f"{phase}: n/a")
        rule(3, "prod dual-mem, single-agent, single-mem fg tok/s >= 0.97x off",
             not r3_fail, "all ok" if not r3_fail else "; ".join(r3_fail))

        # rule 4: VRAM <= off + 64 MiB (every phase)
        r4_fail = []
        for phase in PHASES:
            v = spec_rate_vram = vram_mib(outdir, f"{best_cfg}-prod", phase)
            ov = vram_mib(outdir, "off-prod", phase)
            if v is None or ov is None:
                continue
            d = v - ov
            if d > 64.0:
                r4_fail.append(f"{phase}: {v:.0f} MiB vs off {ov:.0f} MiB (+{d:.0f} MiB)")
        rule(4, "VRAM <= off + 64 MiB (after first fg request, every phase)",
             not r4_fail, "max +%.1f MiB" % max((vram_mib(outdir, f'{best_cfg}-prod', p)
                                                 - vram_mib(outdir, "off-prod", p))
                                                for p in PHASES if
                                                vram_mib(outdir, f'{best_cfg}-prod', p) is not None and
                                                vram_mib(outdir, "off-prod", p) is not None))
             if not r4_fail else "; ".join(r4_fail))

        # rule 5: tool_call_json_valid >= off (greedy and prod, per phase)
        r5_fail = []
        for s in SAMPLINGS:
            for phase in PHASES:
                a_arm = f"{best_cfg}-{s}"
                if a_arm not in data or "off-%s" % s not in data:
                    continue
                v = valid_rate(fg_rows(data[a_arm], phase))
                o = valid_rate(fg_rows(data["off-%s" % s], phase))
                if v is None or o is None:
                    continue
                if v < o:
                    r5_fail.append(f"{s} {phase}: {pct(v)} vs off {pct(o)}")
        rule(5, "tool_call_json_valid rate >= off (greedy+prod, per phase)",
             not r5_fail, "all ok" if not r5_fail else "; ".join(r5_fail))

        # rule 6: greedy identity not below control by > 10 points
        r6_fail = []
        for row in identity:
            if row.get("config") != best_cfg:
                continue
            ip = row.get("ident_rate")
            cp = row.get("control_rate")
            if ip is None or cp is None:
                r6_fail.append(f"{row['phase']}: rates n/a")
                continue
            if ip < cp - 0.10:
                r6_fail.append(
                    f"{row['phase']}: identical {pct(ip)} vs control {pct(cp)} "
                    f"(-{abs(ip - cp):.1f} pts, control n={row['control_n']} "
                    f"{row['control_same']}/{row['control_n']} same)")
        rule(6, "greedy identical-output rate >= off dual-vs-single control - 10 pts",
             not r6_fail, "all ok" if not r6_fail else "; ".join(r6_fail))

    all_ok = bool(rule_details) and all(r["status"] for r in rule_details)
    deploy = best_cfg is not None and all_ok

    # ---- write summary.md ----
    lines = []
    lines.append("# M1 ngram self-speculation — decision summary")
    lines.append("")
    lines.append(f"*Outdir:* `{outdir}`  ")
    lines.append(f"*Arms:* `{', '.join(sorted(arms, key=lambda a: (CONFIGS.index(a) if a.rsplit('-',1)[0] in CONFIGS else 9, a)))}`"
                 if False else f"*Arms:* `{', '.join(arms)}`"
                 )
    lines.append(f"*Missing arms:* `{', '.join(missing_arms)}`" if missing_arms else "")
    lines.append("")
    lines.append("Foreground (fg) rows only. Token-weighted decode tok/s = "
                 "`sum(predicted_n)/sum(predicted_ms)*1000`. Null draft fields mean "
                 "0 drafted (llama.cpp reports `draft_n`/`draft_n_accepted` only when > 0). "
                 "VRAM = memory used after the first fg request of each phase, fresh server "
                 "(private :8089, production flags; `--spec-type` added for spec arms). "
                 "Identity (greedy) compares the hashed blob = "
                 "reasoning_content + content + sorted tool_calls JSON, per "
                 "`spec_replay.py`; first-divergence index comes from the full outputs "
                 "`bench/.replay/outputs/*.jsonl` (gitignored; host only).")
    lines.append("")
    lines.append("## Server command per config (from notes.txt)")
    for c in CONFIGS:
        if c in cmds:
            lines.append(f"- **{c}:** `{cmds[c]}`")
        if c in warnings:
            lines.append(f"  - server log: `{warnings[c]}`")
    lines.append("")
    lines.append("## Metrics per (config, sampling, phase)")
    lines.append("")
    lines.append("| config | sampling | phase | n | tok/s (token-weighted) | median tok/s | acceptance | "
                 "draft gen tok/gen tok | speedup vs off | tool_call_json_valid | "
                 "VRAM MiB | VRAM vs off (MiB) |")
    lines.append("|---|---|---|---|---:|---:|---:|---:|---:|---:|---:|---:|")
    for mr in metric_rows:
        vram_d = f"{mr['vram_delta_mib']:+.0f}" if mr["vram_delta_mib"] is not None else "n/a"
        lines.append("| %s | %s | %s | %d | %s | %s | %s | %s | %s | %s | %s | %s |" % (
            mr["config"], mr["sampling"], mr["phase"], mr["n"],
            fnum(mr["tok_s"], 1), fnum(mr["median_toks_s"], 1),
            "n/a" if mr["acceptance"] is None else f"{mr['acceptance']:.3f}",
            "n/a" if mr["draft_tokens_per_generated_token"] is None
            else f"{mr['draft_tokens_per_generated_token']:.3f}",
            "n/a" if mr["speedup_vs_off"] is None else f"{mr['speedup_vs_off']:.2f}x",
            pct(mr["tool_call_json_valid"]),
            "n/a" if mr["vram_mib"] is None else f"{mr['vram_mib']:.0f}",
            vram_d,
        ))
    lines.append("")
    lines.append("## Output identity (greedy only, same phase + id vs off-greedy)")
    lines.append("")
    lines.append("| arm | phase | n | same as off | identical | first-divergence char index |")
    lines.append("|---|---|---:|---:|---:|---|")
    for row in identity:
        mism = row["mismatches"]
        same = row["same"]
        n = row["n"]
        rate_s = pct(row.get("ident_rate"))
        lines.append("| %s | %s | %d | %d | %s | %s |" % (
            row["config"] + "-greedy", row["phase"], n, same, rate_s,
            div_col(mismatches:=mismatches if isinstance(mismatches, list) else [])))
    lines.append("")
    lines.append("### off dual-vs-single control (batching baseline, no speculation)")
    lines.append("")
    lines.append("| phase (dual vs single) | n (dual fg) | same sha | identical | first-divergence char index |")
    lines.append("|---|---:|---:|---:|---|")
    for phase in PHASES:
        ctl = control.get(phase, {})
        lines.append("| %s (vs %s) | %d | %d | %s | %s |" % (
            phase, phase.replace("dual-", "single-").replace("single-", "dual-"),
            ctl.get("n", 0), ctl.get("same", 0),
            pct(ctl.get("same") and ctl["same"] / ctl["n"] if ctl.get("n") else None) if False else
            (pct(ctl["same"] / ctl["n"]) if ctl.get("n") else "n/a"),
            div_col(ctl.get("mismatches", []))))
    lines.append("")
    lines.append("## Deployment rules (best spec arm = `%s`, prod sampling)") % (best_cfg or "n/a")
    lines.append("")
    lines.append("| # | rule | result | value |")
    lines.append("|---|---|---|---|")
    for r in rule_details:
        status = "PASS" if r["status"] else "FAIL"
        lines.append("| %d | %s | **%s** | %s |" % (r["n"], r["rule"], status, r["value"]))
    lines.append("")
    lines.append("## Decision")
    if deploy:
        lines.append("**Deploy warranted:** best arm `%s` satisfies all six rules." % best_cfg)
        lines.append("Create `serving/candidates/bonsai-2-27b.ngram.yaml` (copy of the live "
                     "entry with only the spec flags appended to `cmd`) and submit an `infra` "
                     "request. `deploy.json` will then hold the returned infra JSON.")
    else:
        why = [f"rule {r['n']}: {r['value']}" for r in rule_details if not r["status"]]
        lines.append("**No deployment.** Rules failed for the best arm "
                     f"`{best_cfg}`: " + "; ".join(why) + ". "
                     "The live `bonsai-2-27b` entry is left unchanged.")
    lines.append("")
    lines.append("_Computed by `bench/spec_summarize.py` from "
                 "`bench/results/2026-10-12/m1-ngram/replay/*/requests.jsonl`._")

    with open(os.path.join(outdir, "summary.md"), "w") as f:
        f.write("\n".join(lines) + "\n")

    # ---- summary.json ----
    def summ(rows_d):
        return {
            "n": rows_d.get("n"), "same": rows_d.get("same"),
            "ident_rate": rows_d.get("ident_rate"),
            "mismatches": [
                {"id": m["id"], "first_divergence_index": m["idx"], "note": m["note"]}
                for m in rows_d.get("mismatches", [])
            ],
        }

    summary = {
        "outdir": outdir,
        "arms": arms,
        "missing_arms": missing_arms,
        "best_config": best_cfg,
        "metrics": [
            {k: v for k, v in mr.items()
             if v is not None or k in ("speedup_vs_off", "vram_delta_mib", "acceptance",
                                       "draft_tokens_per_generated_token")}
            for mr in metric_rows
        ],
        "identity": identity,
        "identity_control": {phase: control[phase] for phase in control},
        "rules": rule_details,
        "decision": {
            "deploy": deploy,
            "config": best_cfg if deploy else None,
        },
    }
    with open(os.path.join(outdir, "summary.json"), "w") as f:
        json.dump(summary, f, indent=2, default=str)
        f.write("\n")

    # ---- deploy.json only when NOT deploying ----
    if not deploy:
        why = [f"rule {r['n']}: {r['value']}" for r in rule_details if not r["status"]]
        with open(os.path.join(outdir, "deploy.json"), "w") as f:
            json.dump({"deployed": False, "why": why}, f, indent=2)
            f.write("\n")

    print("wrote %s, %s" % (os.path.join(outdir, "summary.md"),
                             os.path.join(outdir, "summary.json")))
    if not deploy:
        print("deploy.json: deployed=false, why=%r" % (why[:2] + ["..."] if len(why) > 2 else why))
    else:
        print("deployment warranted for %s" % best_cfg)


if __name__ == "__main__":
    main()

